        color_descriptor.pixelFormat = MTLPixelFormatRGBA8Unorm;
        color_descriptor.width = width;
        color_descriptor.height = height;
        color_descriptor.arrayLength = layers;
        color_descriptor.mipmapLevelCount = 1;
