static int test_packed_render_against_native(
    id<MTLDevice> native_device, id<MTLDevice> adapter_device,
    id<MTLFunction> native_vertex_function, id<MTLFunction> native_fragment_function,
    id<MTLFunction> adapter_vertex_function, id<MTLFunction> adapter_fragment_function) {
    enum { width = 8, height = 8, max_byte_count = width * height * 4 };
    const struct {
        MTLPixelFormat format;
        NSUInteger bytes_per_pixel;
        const char *name;
    } formats[] = {
        {MTLPixelFormatB5G6R5Unorm, 2, "B5G6R5Unorm"},
        {MTLPixelFormatA1BGR5Unorm, 2, "A1BGR5Unorm"},
        {MTLPixelFormatABGR4Unorm, 2, "ABGR4Unorm"},
        {MTLPixelFormatBGR5A1Unorm, 2, "BGR5A1Unorm"},
        {MTLPixelFormatRGB10A2Unorm, 4, "RGB10A2Unorm"},
        {MTLPixelFormatBGR10A2Unorm, 4, "BGR10A2Unorm"},
        {MTLPixelFormatRG11B10Float, 4, "RG11B10Float"},
        {MTLPixelFormatRGB9E5Float, 4, "RGB9E5Float"},
    };
    const zpu_metal_vertex vertices[] = {
        {{-1.0f, -1.0f, 0.5f, 1.0f}, {0.125f, 0.375f, 0.625f, 0.875f}},
        {{ 1.0f, -1.0f, 0.5f, 1.0f}, {0.125f, 0.375f, 0.625f, 0.875f}},
        {{ 1.0f,  1.0f, 0.5f, 1.0f}, {0.125f, 0.375f, 0.625f, 0.875f}},
        {{-1.0f, -1.0f, 0.5f, 1.0f}, {0.125f, 0.375f, 0.625f, 0.875f}},
        {{ 1.0f,  1.0f, 0.5f, 1.0f}, {0.125f, 0.375f, 0.625f, 0.875f}},
        {{-1.0f,  1.0f, 0.5f, 1.0f}, {0.125f, 0.375f, 0.625f, 0.875f}},
    };
    for (NSUInteger index = 0; index < sizeof(formats) / sizeof(formats[0]); ++index) {
        MTLRenderPipelineDescriptor *native_pipeline_descriptor = [MTLRenderPipelineDescriptor new];
        native_pipeline_descriptor.vertexFunction = native_vertex_function;
        native_pipeline_descriptor.fragmentFunction = native_fragment_function;
        native_pipeline_descriptor.colorAttachments[0].pixelFormat = formats[index].format;
        MTLRenderPipelineDescriptor *adapter_pipeline_descriptor = [MTLRenderPipelineDescriptor new];
        adapter_pipeline_descriptor.vertexFunction = adapter_vertex_function;
        adapter_pipeline_descriptor.fragmentFunction = adapter_fragment_function;
        adapter_pipeline_descriptor.colorAttachments[0].pixelFormat = formats[index].format;
        NSError *native_error = nil;
        NSError *adapter_error = nil;
        id<MTLRenderPipelineState> native_pipeline =
            [native_device newRenderPipelineStateWithDescriptor:native_pipeline_descriptor error:&native_error];
        id<MTLRenderPipelineState> adapter_pipeline =
            [adapter_device newRenderPipelineStateWithDescriptor:adapter_pipeline_descriptor error:&adapter_error];
        MTLTextureDescriptor *texture_descriptor =
            [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:formats[index].format
                                                                width:width height:height mipmapped:NO];
        texture_descriptor.storageMode = MTLStorageModeShared;
        texture_descriptor.usage = MTLTextureUsageRenderTarget;
        id<MTLTexture> native_texture = [native_device newTextureWithDescriptor:texture_descriptor];
        id<MTLTexture> adapter_texture = [adapter_device newTextureWithDescriptor:texture_descriptor];
        id<MTLBuffer> native_buffer =
            [native_device newBufferWithBytes:vertices length:sizeof(vertices) options:MTLResourceStorageModeShared];
        id<MTLBuffer> adapter_buffer =
            [adapter_device newBufferWithBytes:vertices length:sizeof(vertices) options:MTLResourceStorageModeShared];
        if (native_pipeline == nil || adapter_pipeline == nil || native_texture == nil || adapter_texture == nil ||
            native_buffer == nil || adapter_buffer == nil) {
            fail_with_error(formats[index].name, adapter_error ?: native_error);
            return 167;
        }
        MTLRenderPassDescriptor *native_pass = [MTLRenderPassDescriptor renderPassDescriptor];
        native_pass.colorAttachments[0].texture = native_texture;
        native_pass.colorAttachments[0].loadAction = MTLLoadActionClear;
        native_pass.colorAttachments[0].storeAction = MTLStoreActionStore;
        native_pass.colorAttachments[0].clearColor = MTLClearColorMake(0, 0, 0, 0);
        MTLRenderPassDescriptor *adapter_pass = [native_pass copy];
        adapter_pass.colorAttachments[0].texture = adapter_texture;
        id<MTLCommandBuffer> native_command_buffer = [[native_device newCommandQueue] commandBuffer];
        id<MTLCommandBuffer> adapter_command_buffer = [[adapter_device newCommandQueue] commandBuffer];
        id<MTLRenderCommandEncoder> native_encoder = [native_command_buffer renderCommandEncoderWithDescriptor:native_pass];
        id<MTLRenderCommandEncoder> adapter_encoder = [adapter_command_buffer renderCommandEncoderWithDescriptor:adapter_pass];
        [native_encoder setRenderPipelineState:native_pipeline];
        [native_encoder setVertexBuffer:native_buffer offset:0 atIndex:0];
        [native_encoder drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:6];
        [native_encoder endEncoding];
        [adapter_encoder setRenderPipelineState:adapter_pipeline];
        [adapter_encoder setVertexBuffer:adapter_buffer offset:0 atIndex:0];
        [adapter_encoder drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:6];
        [adapter_encoder endEncoding];
        [native_command_buffer commit];
        [adapter_command_buffer commit];
        [native_command_buffer waitUntilCompleted];
        [adapter_command_buffer waitUntilCompleted];
        uint8_t native_pixels[max_byte_count];
        uint8_t adapter_pixels[max_byte_count];
        const NSUInteger byte_count = width * height * formats[index].bytes_per_pixel;
        [native_texture getBytes:native_pixels bytesPerRow:width * formats[index].bytes_per_pixel
                       fromRegion:MTLRegionMake2D(0, 0, width, height) mipmapLevel:0];
        [adapter_texture getBytes:adapter_pixels bytesPerRow:width * formats[index].bytes_per_pixel
                         fromRegion:MTLRegionMake2D(0, 0, width, height) mipmapLevel:0];
        if (native_command_buffer.status != MTLCommandBufferStatusCompleted ||
            adapter_command_buffer.status != MTLCommandBufferStatusCompleted ||
            memcmp(native_pixels, adapter_pixels, byte_count) != 0) {
            size_t mismatch = 0;
            while (mismatch < byte_count && native_pixels[mismatch] == adapter_pixels[mismatch]) mismatch += 1;
            fprintf(stderr, "metal-pixel: %s render mismatch at byte %zu native=%u adapter=%u statuses=%ld/%ld\n",
                    formats[index].name, mismatch,
                    mismatch < byte_count ? native_pixels[mismatch] : 0,
                    mismatch < byte_count ? adapter_pixels[mismatch] : 0,
                    (long)native_command_buffer.status, (long)adapter_command_buffer.status);
            return 168;
        }
    }
    return 0;
}

static int test_packed_mipmaps_against_native(id<MTLDevice> native_device, id<MTLDevice> adapter_device) {
    enum { width = 8, height = 8, mipmap_levels = 4 };
    const struct {
        MTLPixelFormat format;
        NSUInteger bytes_per_pixel;
        const char *name;
    } formats[] = {
        {MTLPixelFormatB5G6R5Unorm, 2, "B5G6R5Unorm mipmaps"},
        {MTLPixelFormatA1BGR5Unorm, 2, "A1BGR5Unorm mipmaps"},
        {MTLPixelFormatABGR4Unorm, 2, "ABGR4Unorm mipmaps"},
        {MTLPixelFormatBGR5A1Unorm, 2, "BGR5A1Unorm mipmaps"},
        {MTLPixelFormatRGB10A2Unorm, 4, "RGB10A2Unorm mipmaps"},
        {MTLPixelFormatBGR10A2Unorm, 4, "BGR10A2Unorm mipmaps"},
        {MTLPixelFormatRG11B10Float, 4, "RG11B10Float mipmaps"},
        {MTLPixelFormatRGB9E5Float, 4, "RGB9E5Float mipmaps"},
    };
    for (NSUInteger index = 0; index < sizeof(formats) / sizeof(formats[0]); ++index) {
        const NSUInteger source_byte_count = width * height * formats[index].bytes_per_pixel;
        uint8_t source_bytes[source_byte_count];
        for (NSUInteger pixel = 0; pixel < width * height; ++pixel) {
            const uint32_t x = (uint32_t)(pixel % width);
            const uint32_t y = (uint32_t)(pixel / width);
            const uint32_t red = x * 4u + y * 6u + 3u;
            const uint32_t green = x * 6u + y * 4u + 5u;
            const uint32_t blue = x * 2u + y * 8u + 7u;
            const uint32_t alpha = 2u;
            uint32_t bits;
            switch (formats[index].format) {
                case MTLPixelFormatB5G6R5Unorm:
                    bits = (((x * 2u + y * 2u + 1u) & 0x1fu) << 11) |
                        (((x * 2u + y * 2u + 2u) & 0x3fu) << 5) |
                        ((x * 2u + y * 2u + 3u) & 0x1fu);
                    break;
                case MTLPixelFormatA1BGR5Unorm:
                    bits = (((x * 2u + y * 2u + 1u) & 0x1fu) << 11) |
                        (((x * 2u + y * 2u + 2u) & 0x1fu) << 6) |
                        (((x * 2u + y * 2u + 3u) & 0x1fu) << 1) | 1u;
                    break;
                case MTLPixelFormatABGR4Unorm:
                    bits = (((x * 2u + y * 2u + 1u) & 0xfu) << 12) |
                        (((x * 2u + y * 2u + 2u) & 0xfu) << 8) |
                        (((x * 2u + y * 2u + 3u) & 0xfu) << 4) | 4u;
                    break;
                case MTLPixelFormatBGR5A1Unorm:
                    bits = (((x * 2u + y * 2u + 1u) & 0x1fu) << 10) |
                        (((x * 2u + y * 2u + 2u) & 0x1fu) << 5) |
                        ((x * 2u + y * 2u + 3u) & 0x1fu) | (1u << 15);
                    break;
                case MTLPixelFormatRGB10A2Unorm:
                    bits = red | (green << 10) | (blue << 20) | (alpha << 30);
                    break;
                case MTLPixelFormatBGR10A2Unorm:
                    bits = blue | (green << 10) | (red << 20) | (alpha << 30);
                    break;
                case MTLPixelFormatRG11B10Float:
                    bits = ((12u << 6) | ((x + y) & 0x3fu)) |
                        (((13u << 6) | ((x * 2u + y) & 0x3fu)) << 11) |
                        (((14u << 5) | ((x + y * 2u) & 0x1fu)) << 22);
                    break;
                case MTLPixelFormatRGB9E5Float:
                    bits = (32u + x * 2u + y) |
                        ((192u + x + y * 2u) << 9) |
                        ((320u + x * 2u + y * 3u) << 18) | (15u << 27);
                    break;
                default:
                    bits = 0;
                    break;
            }
            memcpy(source_bytes + pixel * formats[index].bytes_per_pixel, &bits, formats[index].bytes_per_pixel);
        }
        MTLTextureDescriptor *native_descriptor =
            [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:formats[index].format
                                                                width:width height:height mipmapped:YES];
        native_descriptor.mipmapLevelCount = mipmap_levels;
        native_descriptor.storageMode = MTLStorageModeShared;
        native_descriptor.usage = MTLTextureUsageShaderRead;
        MTLTextureDescriptor *adapter_descriptor = [native_descriptor copy];
        id<MTLTexture> native_texture = [native_device newTextureWithDescriptor:native_descriptor];
        id<MTLTexture> adapter_texture = [adapter_device newTextureWithDescriptor:adapter_descriptor];
        if (native_texture == nil || adapter_texture == nil) {
            fprintf(stderr, "metal-pixel: %s texture allocation failed\n", formats[index].name);
            return 169;
        }
        [native_texture replaceRegion:MTLRegionMake2D(0, 0, width, height)
                           mipmapLevel:0 withBytes:source_bytes
                         bytesPerRow:width * formats[index].bytes_per_pixel];
        [adapter_texture replaceRegion:MTLRegionMake2D(0, 0, width, height)
                            mipmapLevel:0 withBytes:source_bytes
                          bytesPerRow:width * formats[index].bytes_per_pixel];
        id<MTLCommandBuffer> native_command_buffer = [[native_device newCommandQueue] commandBuffer];
        id<MTLCommandBuffer> adapter_command_buffer = [[adapter_device newCommandQueue] commandBuffer];
        id<MTLBlitCommandEncoder> native_encoder = [native_command_buffer blitCommandEncoder];
        id<MTLBlitCommandEncoder> adapter_encoder = [adapter_command_buffer blitCommandEncoder];
        [native_encoder generateMipmapsForTexture:native_texture];
        [adapter_encoder generateMipmapsForTexture:adapter_texture];
        [native_encoder endEncoding];
        [adapter_encoder endEncoding];
        [native_command_buffer commit];
        [adapter_command_buffer commit];
        [native_command_buffer waitUntilCompleted];
        [adapter_command_buffer waitUntilCompleted];
        if (native_command_buffer.status != MTLCommandBufferStatusCompleted ||
            adapter_command_buffer.status != MTLCommandBufferStatusCompleted) {
            fprintf(stderr, "metal-pixel: %s command failed statuses=%ld/%ld\n", formats[index].name,
                    (long)native_command_buffer.status, (long)adapter_command_buffer.status);
            return 170;
        }
        for (NSUInteger level = 1; level < mipmap_levels; ++level) {
            const NSUInteger level_width = MAX(width >> level, 1);
            const NSUInteger level_height = MAX(height >> level, 1);
            const NSUInteger level_byte_count = level_width * level_height * formats[index].bytes_per_pixel;
            uint8_t native_level[level_byte_count];
            uint8_t adapter_level[level_byte_count];
            [native_texture getBytes:native_level bytesPerRow:level_width * formats[index].bytes_per_pixel
                           fromRegion:MTLRegionMake2D(0, 0, level_width, level_height) mipmapLevel:level];
            [adapter_texture getBytes:adapter_level bytesPerRow:level_width * formats[index].bytes_per_pixel
                            fromRegion:MTLRegionMake2D(0, 0, level_width, level_height) mipmapLevel:level];
            if (memcmp(native_level, adapter_level, level_byte_count) != 0) {
                size_t mismatch = 0;
                while (mismatch < level_byte_count && native_level[mismatch] == adapter_level[mismatch]) mismatch += 1;
                fprintf(stderr, "metal-pixel: %s level %lu mismatch at byte %zu native=%u adapter=%u\n",
                        formats[index].name, (unsigned long)level, mismatch,
                        mismatch < level_byte_count ? native_level[mismatch] : 0,
                        mismatch < level_byte_count ? adapter_level[mismatch] : 0);
                return 171;
            }
        }
    }
    return 0;
}

static int test_packed_3d_mipmaps_against_native(id<MTLDevice> native_device, id<MTLDevice> adapter_device) {
    enum { width = 4, height = 4, depth = 4, mipmap_levels = 3 };
    const struct {
        MTLPixelFormat format;
        NSUInteger bytes_per_pixel;
        const char *name;
    } formats[] = {
        {MTLPixelFormatB5G6R5Unorm, 2, "B5G6R5Unorm 3D mipmaps"},
        {MTLPixelFormatA1BGR5Unorm, 2, "A1BGR5Unorm 3D mipmaps"},
        {MTLPixelFormatABGR4Unorm, 2, "ABGR4Unorm 3D mipmaps"},
        {MTLPixelFormatBGR5A1Unorm, 2, "BGR5A1Unorm 3D mipmaps"},
        {MTLPixelFormatRGB10A2Unorm, 4, "RGB10A2Unorm 3D mipmaps"},
        {MTLPixelFormatBGR10A2Unorm, 4, "BGR10A2Unorm 3D mipmaps"},
        {MTLPixelFormatRG11B10Float, 4, "RG11B10Float 3D mipmaps"},
        {MTLPixelFormatRGB9E5Float, 4, "RGB9E5Float 3D mipmaps"},
    };
    for (NSUInteger index = 0; index < sizeof(formats) / sizeof(formats[0]); ++index) {
        const NSUInteger source_byte_count = width * height * depth * formats[index].bytes_per_pixel;
        uint8_t source_bytes[source_byte_count];
        for (NSUInteger z = 0; z < depth; ++z) {
            for (NSUInteger y = 0; y < height; ++y) {
                for (NSUInteger x = 0; x < width; ++x) {
                    const uint32_t red = (uint32_t)(x + y + z * 2u + 1u);
                    const uint32_t green = (uint32_t)(x + y + z * 2u + 2u);
                    const uint32_t blue = (uint32_t)(x + y + z * 2u + 3u);
                    const uint32_t pixel = (uint32_t)(z * width * height + y * width + x);
                    uint32_t bits;
                    switch (formats[index].format) {
                        case MTLPixelFormatB5G6R5Unorm:
                            bits = (((x + y + z * 2u + 1u) & 0x1fu) << 11) |
                                (((x + y + z * 2u + 2u) & 0x3fu) << 5) |
                                ((x + y + z * 2u + 3u) & 0x1fu);
                            break;
                        case MTLPixelFormatA1BGR5Unorm:
                            bits = (((x + y + z * 2u + 1u) & 0x1fu) << 11) |
                                (((x + y + z * 2u + 2u) & 0x1fu) << 6) |
                                (((x + y + z * 2u + 3u) & 0x1fu) << 1) | 1u;
                            break;
                        case MTLPixelFormatABGR4Unorm:
                            bits = (((x + y + z * 2u + 1u) & 0xfu) << 12) |
                                (((x + y + z * 2u + 2u) & 0xfu) << 8) |
                                (((x + y + z * 2u + 3u) & 0xfu) << 4) | 4u;
                            break;
                        case MTLPixelFormatBGR5A1Unorm:
                            bits = (((x + y + z * 2u + 1u) & 0x1fu) << 10) |
                                (((x + y + z * 2u + 2u) & 0x1fu) << 5) |
                                ((x + y + z * 2u + 3u) & 0x1fu) | (1u << 15);
                            break;
                        case MTLPixelFormatRGB10A2Unorm:
                            bits = red | (green << 10) | (blue << 20) | (2u << 30);
                            break;
                        case MTLPixelFormatBGR10A2Unorm:
                            bits = blue | (green << 10) | (red << 20) | (2u << 30);
                            break;
                        case MTLPixelFormatRG11B10Float:
                            bits = ((12u << 6) | ((x + y + z * 2u + 1u) & 0x3fu)) |
                                (((13u << 6) | ((x * 2u + y + z * 2u + 2u) & 0x3fu)) << 11) |
                                (((14u << 5) | ((x + y * 2u + z + 3u) & 0x1fu)) << 22);
                            break;
                        case MTLPixelFormatRGB9E5Float:
                            bits = (32u + x * 2u + y + z * 3u) |
                                ((192u + x + y * 2u + z * 3u) << 9) |
                                ((320u + x * 2u + y * 3u + z * 4u) << 18) | (15u << 27);
                            break;
                        default:
                            bits = pixel;
                            break;
                    }
                    memcpy(source_bytes + pixel * formats[index].bytes_per_pixel, &bits,
                           formats[index].bytes_per_pixel);
                }
            }
        }
        MTLTextureDescriptor *native_descriptor = [MTLTextureDescriptor new];
        native_descriptor.textureType = MTLTextureType3D;
        native_descriptor.pixelFormat = formats[index].format;
        native_descriptor.width = width;
        native_descriptor.height = height;
        native_descriptor.depth = depth;
        native_descriptor.arrayLength = 1;
        native_descriptor.mipmapLevelCount = mipmap_levels;
        native_descriptor.sampleCount = 1;
        native_descriptor.mipmapLevelCount = mipmap_levels;
        native_descriptor.storageMode = MTLStorageModeShared;
        native_descriptor.usage = MTLTextureUsageShaderRead;
        MTLTextureDescriptor *adapter_descriptor = [native_descriptor copy];
        id<MTLTexture> native_texture = [native_device newTextureWithDescriptor:native_descriptor];
        id<MTLTexture> adapter_texture = [adapter_device newTextureWithDescriptor:adapter_descriptor];
        if (native_texture == nil || adapter_texture == nil) {
            fprintf(stderr, "metal-pixel: %s texture allocation failed\n", formats[index].name);
            return 172;
        }
        [native_texture replaceRegion:MTLRegionMake3D(0, 0, 0, width, height, depth)
                           mipmapLevel:0 slice:0 withBytes:source_bytes
                         bytesPerRow:width * formats[index].bytes_per_pixel
                       bytesPerImage:width * height * formats[index].bytes_per_pixel];
        [adapter_texture replaceRegion:MTLRegionMake3D(0, 0, 0, width, height, depth)
                            mipmapLevel:0 slice:0 withBytes:source_bytes
                          bytesPerRow:width * formats[index].bytes_per_pixel
                        bytesPerImage:width * height * formats[index].bytes_per_pixel];
        id<MTLCommandQueue> native_queue = [native_device newCommandQueue];
        id<MTLCommandQueue> adapter_queue = [adapter_device newCommandQueue];
        id<MTLCommandBuffer> native_command_buffer = [native_queue commandBuffer];
        id<MTLCommandBuffer> adapter_command_buffer = [adapter_queue commandBuffer];
        id<MTLBlitCommandEncoder> native_encoder = [native_command_buffer blitCommandEncoder];
        id<MTLBlitCommandEncoder> adapter_encoder = [adapter_command_buffer blitCommandEncoder];
        [native_encoder generateMipmapsForTexture:native_texture];
        [adapter_encoder generateMipmapsForTexture:adapter_texture];
        [native_encoder endEncoding];
        [adapter_encoder endEncoding];
        [native_command_buffer commit];
        [adapter_command_buffer commit];
        [native_command_buffer waitUntilCompleted];
        [adapter_command_buffer waitUntilCompleted];
        if (native_command_buffer.status != MTLCommandBufferStatusCompleted ||
            adapter_command_buffer.status != MTLCommandBufferStatusCompleted) {
            fprintf(stderr, "metal-pixel: %s command failed statuses=%ld/%ld\n", formats[index].name,
                    (long)native_command_buffer.status, (long)adapter_command_buffer.status);
            return 173;
        }
        for (NSUInteger level = 1; level < mipmap_levels; ++level) {
            const NSUInteger level_width = MAX(width >> level, 1);
            const NSUInteger level_height = MAX(height >> level, 1);
            const NSUInteger level_depth = MAX(depth >> level, 1);
            const NSUInteger level_byte_count = level_width * level_height * level_depth * formats[index].bytes_per_pixel;
            uint8_t native_level[level_byte_count];
            uint8_t adapter_level[level_byte_count];
            [native_texture getBytes:native_level
                         bytesPerRow:level_width * formats[index].bytes_per_pixel
                       bytesPerImage:level_width * level_height * formats[index].bytes_per_pixel
                          fromRegion:MTLRegionMake3D(0, 0, 0, level_width, level_height, level_depth)
                         mipmapLevel:level slice:0];
            [adapter_texture getBytes:adapter_level
                          bytesPerRow:level_width * formats[index].bytes_per_pixel
                        bytesPerImage:level_width * level_height * formats[index].bytes_per_pixel
                           fromRegion:MTLRegionMake3D(0, 0, 0, level_width, level_height, level_depth)
                          mipmapLevel:level slice:0];
            if (memcmp(native_level, adapter_level, level_byte_count) != 0) {
                size_t mismatch = 0;
                while (mismatch < level_byte_count && native_level[mismatch] == adapter_level[mismatch]) mismatch += 1;
                fprintf(stderr, "metal-pixel: %s level %lu mismatch at byte %zu native=%u adapter=%u\n",
                        formats[index].name, (unsigned long)level, mismatch,
                        mismatch < level_byte_count ? native_level[mismatch] : 0,
                        mismatch < level_byte_count ? adapter_level[mismatch] : 0);
                return 174;
            }
        }
    }
    return 0;
}

static int test_color_sampling_against_native(
    id<MTLDevice> native_device, id<MTLDevice> adapter_device,
    id<MTLFunction> native_vertex_function, id<MTLFunction> native_sample_function,
    id<MTLFunction> adapter_vertex_function, id<MTLFunction> adapter_sample_function) {
    enum { width = 8, height = 8, max_byte_count = width * height * 16 };
    const struct {
        MTLPixelFormat format;
        NSUInteger bytes_per_pixel;
        const char *name;
    } formats[] = {
        {MTLPixelFormatR8Unorm_sRGB, 1, "R8Unorm_sRGB"},
        {MTLPixelFormatRG8Unorm_sRGB, 2, "RG8Unorm_sRGB"},
        {MTLPixelFormatRGBA8Unorm_sRGB, 4, "RGBA8Unorm_sRGB"},
        {MTLPixelFormatBGRA8Unorm_sRGB, 4, "BGRA8Unorm_sRGB"},
        {MTLPixelFormatB5G6R5Unorm, 2, "B5G6R5Unorm"},
        {MTLPixelFormatA1BGR5Unorm, 2, "A1BGR5Unorm"},
        {MTLPixelFormatABGR4Unorm, 2, "ABGR4Unorm"},
        {MTLPixelFormatBGR5A1Unorm, 2, "BGR5A1Unorm"},
        {MTLPixelFormatRGB10A2Unorm, 4, "RGB10A2Unorm"},
        {MTLPixelFormatBGR10A2Unorm, 4, "BGR10A2Unorm"},
        {MTLPixelFormatRG11B10Float, 4, "RG11B10Float"},
        {MTLPixelFormatRGB9E5Float, 4, "RGB9E5Float"},
    };
    const zpu_metal_vertex vertices[] = {
        {{-1.0f, -1.0f, 0.5f, 1.0f}, {0.0625f, 0.0625f, 0.0f, 1.0f}},
        {{ 1.0f, -1.0f, 0.5f, 1.0f}, {0.9375f, 0.0625f, 0.0f, 1.0f}},
        {{ 1.0f,  1.0f, 0.5f, 1.0f}, {0.9375f, 0.9375f, 0.0f, 1.0f}},
        {{-1.0f, -1.0f, 0.5f, 1.0f}, {0.0625f, 0.0625f, 0.0f, 1.0f}},
        {{ 1.0f,  1.0f, 0.5f, 1.0f}, {0.9375f, 0.9375f, 0.0f, 1.0f}},
        {{-1.0f,  1.0f, 0.5f, 1.0f}, {0.0625f, 0.9375f, 0.0f, 1.0f}},
    };
    for (NSUInteger index = 0; index < sizeof(formats) / sizeof(formats[0]); ++index) {
        const NSUInteger bytes_per_pixel = formats[index].bytes_per_pixel;
        const NSUInteger source_byte_count = width * height * bytes_per_pixel;
        uint8_t source_bytes[source_byte_count];
        for (NSUInteger byte = 0; byte < source_byte_count; ++byte) {
            source_bytes[byte] = (uint8_t)((byte * 37u + (byte % bytes_per_pixel) * 53u + 11u) & 0xffu);
        }
        MTLTextureDescriptor *source_descriptor =
            [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:formats[index].format
                                                                width:width height:height mipmapped:NO];
        source_descriptor.storageMode = MTLStorageModeShared;
        source_descriptor.usage = MTLTextureUsageShaderRead;
        id<MTLTexture> native_source = [native_device newTextureWithDescriptor:source_descriptor];
        id<MTLTexture> adapter_source = [adapter_device newTextureWithDescriptor:source_descriptor];
        [native_source replaceRegion:MTLRegionMake2D(0, 0, width, height)
                          mipmapLevel:0 withBytes:source_bytes bytesPerRow:width * bytes_per_pixel];
        [adapter_source replaceRegion:MTLRegionMake2D(0, 0, width, height)
                           mipmapLevel:0 withBytes:source_bytes bytesPerRow:width * bytes_per_pixel];

        MTLRenderPipelineDescriptor *native_pipeline_descriptor = [MTLRenderPipelineDescriptor new];
        native_pipeline_descriptor.vertexFunction = native_vertex_function;
        native_pipeline_descriptor.fragmentFunction = native_sample_function;
        native_pipeline_descriptor.colorAttachments[0].pixelFormat = MTLPixelFormatRGBA32Float;
        NSError *native_error = nil;
        id<MTLRenderPipelineState> native_pipeline =
            [native_device newRenderPipelineStateWithDescriptor:native_pipeline_descriptor error:&native_error];
        MTLRenderPipelineDescriptor *adapter_pipeline_descriptor = [native_pipeline_descriptor copy];
        adapter_pipeline_descriptor.vertexFunction = adapter_vertex_function;
        adapter_pipeline_descriptor.fragmentFunction = adapter_sample_function;
        NSError *adapter_error = nil;
        id<MTLRenderPipelineState> adapter_pipeline =
            [adapter_device newRenderPipelineStateWithDescriptor:adapter_pipeline_descriptor error:&adapter_error];
        MTLTextureDescriptor *output_descriptor =
            [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatRGBA32Float
                                                                width:width height:height mipmapped:NO];
        output_descriptor.storageMode = MTLStorageModeShared;
        output_descriptor.usage = MTLTextureUsageRenderTarget;
        id<MTLTexture> native_output = [native_device newTextureWithDescriptor:output_descriptor];
        id<MTLTexture> adapter_output = [adapter_device newTextureWithDescriptor:output_descriptor];
        id<MTLBuffer> native_buffer =
            [native_device newBufferWithBytes:vertices length:sizeof(vertices) options:MTLResourceStorageModeShared];
        id<MTLBuffer> adapter_buffer =
            [adapter_device newBufferWithBytes:vertices length:sizeof(vertices) options:MTLResourceStorageModeShared];
        MTLSamplerDescriptor *sampler_descriptor = [MTLSamplerDescriptor new];
        sampler_descriptor.minFilter = MTLSamplerMinMagFilterNearest;
        sampler_descriptor.magFilter = MTLSamplerMinMagFilterNearest;
        sampler_descriptor.mipFilter = MTLSamplerMipFilterNotMipmapped;
        id<MTLSamplerState> native_sampler = [native_device newSamplerStateWithDescriptor:sampler_descriptor];
        id<MTLSamplerState> adapter_sampler = [adapter_device newSamplerStateWithDescriptor:sampler_descriptor];
        if (native_source == nil || adapter_source == nil || native_pipeline == nil || adapter_pipeline == nil ||
            native_output == nil || adapter_output == nil || native_buffer == nil || adapter_buffer == nil ||
            native_sampler == nil || adapter_sampler == nil) {
            fail_with_error("sRGB sampling resource allocation failed", adapter_error ?: native_error);
            return 151;
        }
        MTLRenderPassDescriptor *native_pass = [MTLRenderPassDescriptor renderPassDescriptor];
        native_pass.colorAttachments[0].texture = native_output;
        native_pass.colorAttachments[0].loadAction = MTLLoadActionClear;
        native_pass.colorAttachments[0].storeAction = MTLStoreActionStore;
        MTLRenderPassDescriptor *adapter_pass = [native_pass copy];
        adapter_pass.colorAttachments[0].texture = adapter_output;
        id<MTLCommandQueue> native_queue = [native_device newCommandQueue];
        id<MTLCommandQueue> adapter_queue = [adapter_device newCommandQueue];
        id<MTLCommandBuffer> native_command_buffer = [native_queue commandBuffer];
        id<MTLCommandBuffer> adapter_command_buffer = [adapter_queue commandBuffer];
        id<MTLRenderCommandEncoder> native_encoder =
            [native_command_buffer renderCommandEncoderWithDescriptor:native_pass];
        id<MTLRenderCommandEncoder> adapter_encoder =
            [adapter_command_buffer renderCommandEncoderWithDescriptor:adapter_pass];
        [native_encoder setRenderPipelineState:native_pipeline];
        [native_encoder setVertexBuffer:native_buffer offset:0 atIndex:0];
        [native_encoder setFragmentTexture:native_source atIndex:0];
        [native_encoder setFragmentSamplerState:native_sampler atIndex:0];
        [native_encoder drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:6];
        [native_encoder endEncoding];
        [adapter_encoder setRenderPipelineState:adapter_pipeline];
        [adapter_encoder setVertexBuffer:adapter_buffer offset:0 atIndex:0];
        [adapter_encoder setFragmentTexture:adapter_source atIndex:0];
        [adapter_encoder setFragmentSamplerState:adapter_sampler atIndex:0];
        [adapter_encoder drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:6];
        [adapter_encoder endEncoding];
        [native_command_buffer commit];
        [adapter_command_buffer commit];
        [native_command_buffer waitUntilCompleted];
        [adapter_command_buffer waitUntilCompleted];
        uint8_t native_bytes[max_byte_count];
        uint8_t adapter_bytes[max_byte_count];
        [native_output getBytes:native_bytes bytesPerRow:width * 16
                      fromRegion:MTLRegionMake2D(0, 0, width, height) mipmapLevel:0];
        [adapter_output getBytes:adapter_bytes bytesPerRow:width * 16
                       fromRegion:MTLRegionMake2D(0, 0, width, height) mipmapLevel:0];
        const NSUInteger byte_count = width * height * 16;
        if (native_command_buffer.status != MTLCommandBufferStatusCompleted ||
            adapter_command_buffer.status != MTLCommandBufferStatusCompleted ||
            memcmp(native_bytes, adapter_bytes, byte_count) != 0) {
            size_t mismatch = 0;
            while (mismatch < byte_count && native_bytes[mismatch] == adapter_bytes[mismatch]) mismatch += 1;
            fprintf(stderr, "metal-pixel: %s sRGB sample mismatch at byte %zu native=%u adapter=%u\n",
                    formats[index].name, mismatch,
                    mismatch < byte_count ? native_bytes[mismatch] : 0,
                    mismatch < byte_count ? adapter_bytes[mismatch] : 0);
            return 152;
        }
    }
    return 0;
}

static int test_rgba32_integer_transfers_against_native(id<MTLDevice> native_device, id<MTLDevice> adapter_device) {
    enum { width = 3, height = 2, texel_count = width * height, byte_count = texel_count * 16 };
    const struct {
        MTLPixelFormat format;
        const char *name;
    } formats[] = {
        {MTLPixelFormatRGBA32Uint, "RGBA32Uint"},
        {MTLPixelFormatRGBA32Sint, "RGBA32Sint"},
    };
    const uint32_t source[texel_count * 4] = {
        0x00000000, 0x00000001, 0x80000000, 0xffffffff,
        0x10203040, 0x50607080, 0x90a0b0c0, 0xd0e0f000,
        0x7fffffff, 0x80000001, 0x13579bdf, 0x2468ace0,
        0xffffffff, 0x00000000, 0xaaaaaaaa, 0x55555555,
        0x01020304, 0x11223344, 0xdeadbeef, 0xcafebabe,
        0x3f800000, 0x40000000, 0x40400000, 0x40800000,
    };
    for (NSUInteger index = 0; index < sizeof(formats) / sizeof(formats[0]); ++index) {
        MTLTextureDescriptor *descriptor =
            [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:formats[index].format
                                                                width:width height:height mipmapped:NO];
        descriptor.storageMode = MTLStorageModeShared;
        descriptor.usage = MTLTextureUsageShaderRead | MTLTextureUsageShaderWrite;
        id<MTLTexture> native_texture = [native_device newTextureWithDescriptor:descriptor];
        id<MTLTexture> adapter_texture = [adapter_device newTextureWithDescriptor:descriptor];
        if (native_texture == nil || adapter_texture == nil || adapter_texture.allocatedSize != byte_count) {
            fprintf(stderr, "metal-pixel: %s allocation failed\n", formats[index].name);
            return 177;
        }
        [native_texture replaceRegion:MTLRegionMake2D(0, 0, width, height)
                           mipmapLevel:0 withBytes:source bytesPerRow:width * 16];
        [adapter_texture replaceRegion:MTLRegionMake2D(0, 0, width, height)
                            mipmapLevel:0 withBytes:source bytesPerRow:width * 16];
        uint8_t native_bytes[byte_count];
        uint8_t adapter_bytes[byte_count];
        [native_texture getBytes:native_bytes bytesPerRow:width * 16
                       fromRegion:MTLRegionMake2D(0, 0, width, height) mipmapLevel:0];
        [adapter_texture getBytes:adapter_bytes bytesPerRow:width * 16
                        fromRegion:MTLRegionMake2D(0, 0, width, height) mipmapLevel:0];
        if (memcmp(native_bytes, adapter_bytes, byte_count) != 0 ||
            memcmp(adapter_bytes, source, byte_count) != 0) {
            size_t mismatch = 0;
            while (mismatch < byte_count && native_bytes[mismatch] == adapter_bytes[mismatch]) mismatch += 1;
            fprintf(stderr, "metal-pixel: %s transfer mismatch at byte %zu native=%u adapter=%u\n",
                    formats[index].name, mismatch,
                    mismatch < byte_count ? native_bytes[mismatch] : 0,
                    mismatch < byte_count ? adapter_bytes[mismatch] : 0);
            return 178;
        }
    }
    return 0;
}

static int test_metal4_multisample_mrt_against_native(
    id<MTLDevice> native_device, id<MTLDevice> adapter_device,
    id<MTLFunction> native_vertex_function, id<MTLFunction> native_mrt_fragment_function,
    id<MTL4Compiler> adapter_compiler, MTL4RenderPipelineDescriptor *adapter_base_pipeline_descriptor,
    id<MTL4CommandAllocator> adapter_allocator, id<MTL4CommandQueue> adapter_queue) {
    enum { width = 9, height = 7, max_byte_count = width * height * 4 };
    const NSUInteger sample_counts[] = {2, 4};
    const MTLPixelFormat formats[] = {MTLPixelFormatRGBA8Unorm, MTLPixelFormatBGRA8Unorm};
    const MTLClearColor clear_colors[] = {
        MTLClearColorMake(0.05, 0.10, 0.15, 0.20), MTLClearColorMake(0.15, 0.10, 0.05, 0.30),
    };
    const zpu_metal_vertex vertices[] = {
        {{-1.0f, -1.0f, 0.5f, 1.0f}, {0.89f, 0.21f, 0.71f, 0.79f}},
        {{ 1.0f, -1.0f, 0.5f, 1.0f}, {0.89f, 0.21f, 0.71f, 0.79f}},
        {{-1.0f,  1.0f, 0.5f, 1.0f}, {0.89f, 0.21f, 0.71f, 0.79f}},
        {{ 1.0f, -1.0f, 0.5f, 1.0f}, {0.19f, 0.81f, 0.31f, 0.59f}},
        {{ 1.0f,  1.0f, 0.5f, 1.0f}, {0.19f, 0.81f, 0.31f, 0.59f}},
        {{-1.0f,  1.0f, 0.5f, 1.0f}, {0.19f, 0.81f, 0.31f, 0.59f}},
    };
    for (NSUInteger sample_index = 0; sample_index < sizeof(sample_counts) / sizeof(sample_counts[0]); ++sample_index) {
        const NSUInteger sample_count = sample_counts[sample_index];
        MTLRenderPipelineDescriptor *native_pipeline_descriptor = [MTLRenderPipelineDescriptor new];
        native_pipeline_descriptor.vertexFunction = native_vertex_function;
        native_pipeline_descriptor.fragmentFunction = native_mrt_fragment_function;
        native_pipeline_descriptor.rasterSampleCount = sample_count;
        native_pipeline_descriptor.colorAttachments[0].pixelFormat = formats[0];
        native_pipeline_descriptor.colorAttachments[1].pixelFormat = formats[1];
        MTL4RenderPipelineDescriptor *adapter_pipeline_descriptor = [adapter_base_pipeline_descriptor copy];
        adapter_pipeline_descriptor.rasterSampleCount = sample_count;
        adapter_pipeline_descriptor.colorAttachments[0].pixelFormat = formats[0];
        adapter_pipeline_descriptor.colorAttachments[1].pixelFormat = formats[1];
        MTL4LibraryFunctionDescriptor *adapter_fragment_descriptor =
            [adapter_base_pipeline_descriptor.fragmentFunctionDescriptor copy];
        adapter_fragment_descriptor.name = @"zpu_test_mrt_fragment";
        adapter_pipeline_descriptor.fragmentFunctionDescriptor = adapter_fragment_descriptor;
        NSError *native_error = nil;
        NSError *adapter_error = nil;
        id<MTLRenderPipelineState> native_pipeline =
            [native_device newRenderPipelineStateWithDescriptor:native_pipeline_descriptor error:&native_error];
        id<MTLRenderPipelineState> adapter_pipeline =
            [adapter_compiler newRenderPipelineStateWithDescriptor:adapter_pipeline_descriptor
                                                   compilerTaskOptions:nil error:&adapter_error];
        MTLTextureDescriptor *native_msaa_descriptor = [MTLTextureDescriptor new];
        native_msaa_descriptor.textureType = MTLTextureType2DMultisample;
        native_msaa_descriptor.width = width;
        native_msaa_descriptor.height = height;
        native_msaa_descriptor.mipmapLevelCount = 1;
        native_msaa_descriptor.sampleCount = sample_count;
        native_msaa_descriptor.storageMode = MTLStorageModePrivate;
        native_msaa_descriptor.usage = MTLTextureUsageRenderTarget;
        MTLTextureDescriptor *native_resolve_descriptor =
            [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:formats[0]
                                                                width:width height:height mipmapped:NO];
        native_resolve_descriptor.storageMode = MTLStorageModeShared;
        native_resolve_descriptor.usage = MTLTextureUsageRenderTarget;
        id<MTLTexture> native_msaa[2] = {nil, nil};
        id<MTLTexture> adapter_msaa[2] = {nil, nil};
        id<MTLTexture> native_resolve[2] = {nil, nil};
        id<MTLTexture> adapter_resolve[2] = {nil, nil};
        for (NSUInteger attachment = 0; attachment < 2; ++attachment) {
            MTLTextureDescriptor *native_msaa_format_descriptor = [native_msaa_descriptor copy];
            native_msaa_format_descriptor.pixelFormat = formats[attachment];
            MTLTextureDescriptor *native_resolve_format_descriptor = [native_resolve_descriptor copy];
            native_resolve_format_descriptor.pixelFormat = formats[attachment];
            native_msaa[attachment] = [native_device newTextureWithDescriptor:native_msaa_format_descriptor];
            adapter_msaa[attachment] = [adapter_device newTextureWithDescriptor:native_msaa_format_descriptor];
            native_resolve[attachment] = [native_device newTextureWithDescriptor:native_resolve_format_descriptor];
            adapter_resolve[attachment] = [adapter_device newTextureWithDescriptor:native_resolve_format_descriptor];
        }
        id<MTLBuffer> native_buffer =
            [native_device newBufferWithBytes:vertices length:sizeof(vertices) options:MTLResourceStorageModeShared];
        id<MTLBuffer> adapter_buffer =
            [adapter_device newBufferWithBytes:vertices length:sizeof(vertices) options:MTLResourceStorageModeShared];
        if (native_pipeline == nil || adapter_pipeline == nil || native_msaa[0] == nil || native_msaa[1] == nil ||
            adapter_msaa[0] == nil || adapter_msaa[1] == nil || native_resolve[0] == nil || native_resolve[1] == nil ||
            adapter_resolve[0] == nil || adapter_resolve[1] == nil || native_buffer == nil || adapter_buffer == nil) {
            fail_with_error("Metal 4 multisample MRT allocation", adapter_error ?: native_error);
            return 179;
        }
        MTLRenderPassDescriptor *native_pass = [MTLRenderPassDescriptor renderPassDescriptor];
        for (NSUInteger attachment = 0; attachment < 2; ++attachment) {
            native_pass.colorAttachments[attachment].texture = native_msaa[attachment];
            native_pass.colorAttachments[attachment].resolveTexture = native_resolve[attachment];
            native_pass.colorAttachments[attachment].loadAction = MTLLoadActionClear;
            native_pass.colorAttachments[attachment].storeAction = MTLStoreActionMultisampleResolve;
            native_pass.colorAttachments[attachment].clearColor = clear_colors[attachment];
        }
        const MTLSamplePosition sample_positions[] = {
            {0.25f, 0.25f}, {0.75f, 0.75f}, {0.125f, 0.125f}, {0.875f, 0.875f},
        };
        [native_pass setSamplePositions:sample_positions count:sample_count];
        MTL4RenderPassDescriptor *adapter_pass = [MTL4RenderPassDescriptor new];
        for (NSUInteger attachment = 0; attachment < 2; ++attachment) {
            adapter_pass.colorAttachments[attachment].texture = adapter_msaa[attachment];
            adapter_pass.colorAttachments[attachment].resolveTexture = adapter_resolve[attachment];
            adapter_pass.colorAttachments[attachment].loadAction = MTLLoadActionClear;
            adapter_pass.colorAttachments[attachment].storeAction = MTLStoreActionMultisampleResolve;
            adapter_pass.colorAttachments[attachment].clearColor = clear_colors[attachment];
        }
        [adapter_pass setSamplePositions:sample_positions count:sample_count];
        id<MTLCommandQueue> native_queue = [native_device newCommandQueue];
        id<MTLCommandBuffer> native_command_buffer = [native_queue commandBuffer];
        id<MTLRenderCommandEncoder> native_encoder =
            [native_command_buffer renderCommandEncoderWithDescriptor:native_pass];
        id<MTL4CommandBuffer> adapter_command_buffer = [adapter_device newCommandBuffer];
        [adapter_command_buffer beginCommandBufferWithAllocator:adapter_allocator];
        id<MTL4RenderCommandEncoder> adapter_encoder =
            [adapter_command_buffer renderCommandEncoderWithDescriptor:adapter_pass];
        MTL4ArgumentTableDescriptor *table_descriptor = [MTL4ArgumentTableDescriptor new];
        table_descriptor.maxBufferBindCount = 1;
        NSError *table_error = nil;
        id<MTL4ArgumentTable> table = [adapter_device newArgumentTableWithDescriptor:table_descriptor error:&table_error];
        [table setAddress:adapter_buffer.gpuAddress atIndex:0];
        if (native_encoder == nil || adapter_command_buffer == nil || adapter_encoder == nil || table == nil) {
            fail_with_error("Metal 4 multisample MRT encoder allocation", table_error ?: native_error);
            return 180;
        }
        [native_encoder setColorStoreAction:MTLStoreActionStoreAndMultisampleResolve atIndex:0];
        [native_encoder setColorStoreAction:MTLStoreActionStoreAndMultisampleResolve atIndex:1];
        [native_encoder setViewport:(MTLViewport){0.0, 0.0, width, height, 0.0, 1.0}];
        [native_encoder setScissorRect:(MTLScissorRect){0, 0, width, height}];
        [native_encoder setRenderPipelineState:native_pipeline];
        [native_encoder setVertexBuffer:native_buffer offset:0 atIndex:0];
        [native_encoder drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:6];
        [native_encoder endEncoding];
        [adapter_encoder setColorStoreAction:MTLStoreActionStoreAndMultisampleResolve atIndex:0];
        [adapter_encoder setColorStoreAction:MTLStoreActionStoreAndMultisampleResolve atIndex:1];
        [adapter_encoder setViewport:(MTLViewport){0.0, 0.0, width, height, 0.0, 1.0}];
        [adapter_encoder setScissorRect:(MTLScissorRect){0, 0, width, height}];
        [adapter_encoder setRenderPipelineState:adapter_pipeline];
        [adapter_encoder setArgumentTable:table atStages:MTLRenderStageVertex];
        [adapter_encoder drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:6];
        [adapter_encoder endEncoding];
        [native_command_buffer commit];
        [native_command_buffer waitUntilCompleted];
        [adapter_command_buffer endCommandBuffer];
        id<MTL4CommandBuffer> adapter_command_buffers[] = {adapter_command_buffer};
        [adapter_queue commit:adapter_command_buffers count:1];
        uint8_t native_pixels[2][max_byte_count] = {{0}};
        uint8_t adapter_pixels[2][max_byte_count] = {{0}};
        for (NSUInteger attachment = 0; attachment < 2; ++attachment) {
            [native_resolve[attachment] getBytes:native_pixels[attachment] bytesPerRow:width * 4
                                        fromRegion:MTLRegionMake2D(0, 0, width, height) mipmapLevel:0];
            [adapter_resolve[attachment] getBytes:adapter_pixels[attachment] bytesPerRow:width * 4
                                         fromRegion:MTLRegionMake2D(0, 0, width, height) mipmapLevel:0];
            if (memcmp(native_pixels[attachment], adapter_pixels[attachment], max_byte_count) != 0) {
                size_t mismatch = 0;
                while (mismatch < max_byte_count && native_pixels[attachment][mismatch] == adapter_pixels[attachment][mismatch]) mismatch += 1;
                fprintf(stderr, "metal-pixel: Metal 4 %zux MSAA MRT attachment %zu mismatch at byte %zu native=%u adapter=%u native_status=%ld\n",
                        sample_count, attachment, mismatch,
                        mismatch < max_byte_count ? native_pixels[attachment][mismatch] : 0,
                        mismatch < max_byte_count ? adapter_pixels[attachment][mismatch] : 0,
                        (long)native_command_buffer.status);
                fail_with_error("native Metal 4 multisample MRT error", native_command_buffer.error);
                return 181;
            }
        }
        if (native_command_buffer.status != MTLCommandBufferStatusCompleted) {
            fprintf(stderr, "metal-pixel: Metal 4 %zux native multisample MRT command did not complete\n", sample_count);
            return 182;
        }
    }
    return 0;
}

static int test_layered_color_render_against_native(
    id<MTLDevice> native_device, id<MTLDevice> adapter_device,
    id<MTLFunction> native_vertex_function, id<MTLFunction> native_fragment_function,
    id<MTLFunction> adapter_vertex_function, id<MTLFunction> adapter_fragment_function) {
    enum { width = 7, height = 5, layers = 4, max_byte_count = width * height * 4 };
    const MTLPixelFormat formats[] = {MTLPixelFormatRGBA8Unorm, MTLPixelFormatBGRA8Unorm};
    const zpu_metal_vertex vertices[] = {
        {{-0.86f, -0.72f, 0.5f, 1.0f}, {0.91f, 0.17f, 0.63f, 0.81f}},
        {{ 0.78f, -0.43f, 0.5f, 1.0f}, {0.23f, 0.87f, 0.31f, 0.59f}},
        {{-0.21f,  0.84f, 0.5f, 1.0f}, {0.19f, 0.41f, 0.97f, 0.73f}},
    };
    for (NSUInteger format_index = 0; format_index < sizeof(formats) / sizeof(formats[0]); ++format_index) {
        const MTLPixelFormat format = formats[format_index];
        MTLRenderPipelineDescriptor *native_pipeline_descriptor = [MTLRenderPipelineDescriptor new];
        native_pipeline_descriptor.vertexFunction = native_vertex_function;
        native_pipeline_descriptor.fragmentFunction = native_fragment_function;
        native_pipeline_descriptor.inputPrimitiveTopology = MTLPrimitiveTopologyClassTriangle;
        native_pipeline_descriptor.colorAttachments[0].pixelFormat = format;
        MTLRenderPipelineDescriptor *adapter_pipeline_descriptor = [native_pipeline_descriptor copy];
        adapter_pipeline_descriptor.vertexFunction = adapter_vertex_function;
        adapter_pipeline_descriptor.fragmentFunction = adapter_fragment_function;
        NSError *native_error = nil;
        NSError *adapter_error = nil;
        id<MTLRenderPipelineState> native_pipeline =
            [native_device newRenderPipelineStateWithDescriptor:native_pipeline_descriptor error:&native_error];
        id<MTLRenderPipelineState> adapter_pipeline =
            [adapter_device newRenderPipelineStateWithDescriptor:adapter_pipeline_descriptor error:&adapter_error];

        MTLTextureDescriptor *texture_descriptor = [MTLTextureDescriptor new];
        texture_descriptor.textureType = MTLTextureType2DArray;
        texture_descriptor.pixelFormat = format;
        texture_descriptor.width = width;
        texture_descriptor.height = height;
        texture_descriptor.arrayLength = layers;
        texture_descriptor.mipmapLevelCount = 1;
        texture_descriptor.sampleCount = 1;
        texture_descriptor.storageMode = MTLStorageModeShared;
        texture_descriptor.usage = MTLTextureUsageRenderTarget;
        id<MTLTexture> native_texture = [native_device newTextureWithDescriptor:texture_descriptor];
        id<MTLTexture> adapter_texture = [adapter_device newTextureWithDescriptor:texture_descriptor];
        id<MTLBuffer> native_buffer =
            [native_device newBufferWithBytes:vertices length:sizeof(vertices) options:MTLResourceStorageModeShared];
        id<MTLBuffer> adapter_buffer =
            [adapter_device newBufferWithBytes:vertices length:sizeof(vertices) options:MTLResourceStorageModeShared];
        if (native_pipeline == nil || adapter_pipeline == nil || native_texture == nil || adapter_texture == nil ||
            native_buffer == nil || adapter_buffer == nil) {
            fail_with_error("layered render resource/pipeline allocation", adapter_error ?: native_error);
            return 183;
        }

        for (NSUInteger parallel_index = 0; parallel_index < 2; ++parallel_index) {
            MTLRenderPassDescriptor *native_pass = [MTLRenderPassDescriptor renderPassDescriptor];
            native_pass.renderTargetArrayLength = layers;
            native_pass.colorAttachments[0].texture = native_texture;
            native_pass.colorAttachments[0].loadAction = MTLLoadActionClear;
            native_pass.colorAttachments[0].storeAction = MTLStoreActionStore;
            native_pass.colorAttachments[0].clearColor = MTLClearColorMake(0.07, 0.11, 0.19, 1.0);
            MTLRenderPassDescriptor *adapter_pass = [native_pass copy];
            adapter_pass.colorAttachments[0].texture = adapter_texture;

            id<MTLCommandQueue> native_queue = [native_device newCommandQueue];
            id<MTLCommandQueue> adapter_queue = [adapter_device newCommandQueue];
            id<MTLCommandBuffer> native_command_buffer = [native_queue commandBuffer];
            id<MTLCommandBuffer> adapter_command_buffer = [adapter_queue commandBuffer];
            id<MTLParallelRenderCommandEncoder> native_parallel = nil;
            id<MTLParallelRenderCommandEncoder> adapter_parallel = nil;
            id<MTLRenderCommandEncoder> native_encoder = nil;
            id<MTLRenderCommandEncoder> adapter_encoder = nil;
            if (parallel_index == 0) {
                native_encoder = [native_command_buffer renderCommandEncoderWithDescriptor:native_pass];
                adapter_encoder = [adapter_command_buffer renderCommandEncoderWithDescriptor:adapter_pass];
            } else {
                native_parallel = [native_command_buffer parallelRenderCommandEncoderWithDescriptor:native_pass];
                adapter_parallel = [adapter_command_buffer parallelRenderCommandEncoderWithDescriptor:adapter_pass];
                native_encoder = [native_parallel renderCommandEncoder];
                adapter_encoder = [adapter_parallel renderCommandEncoder];
            }
            if (native_encoder == nil || adapter_encoder == nil) {
                fprintf(stderr, "metal-pixel: layered %s encoder creation failed for %s\n",
                        parallel_index == 0 ? "render" : "parallel", format == MTLPixelFormatRGBA8Unorm ? "RGBA8" : "BGRA8");
                return 184;
            }
            [native_encoder setRenderPipelineState:native_pipeline];
            [native_encoder setVertexBuffer:native_buffer offset:0 atIndex:0];
            [native_encoder drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:3 instanceCount:layers - 1 baseInstance:1];
            [native_encoder endEncoding];
            if (native_parallel != nil) [native_parallel endEncoding];
            [adapter_encoder setRenderPipelineState:adapter_pipeline];
            [adapter_encoder setVertexBuffer:adapter_buffer offset:0 atIndex:0];
            [adapter_encoder drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:3 instanceCount:layers - 1 baseInstance:1];
            [adapter_encoder endEncoding];
            if (adapter_parallel != nil) [adapter_parallel endEncoding];
            [native_command_buffer commit];
            [adapter_command_buffer commit];
            [native_command_buffer waitUntilCompleted];
            [adapter_command_buffer waitUntilCompleted];

            uint8_t native_pixels[layers][max_byte_count] = {{0}};
            uint8_t adapter_pixels[layers][max_byte_count] = {{0}};
            for (NSUInteger layer = 0; layer < layers; ++layer) {
                [native_texture getBytes:native_pixels[layer] bytesPerRow:width * 4
                            bytesPerImage:max_byte_count
                             fromRegion:MTLRegionMake3D(0, 0, 0, width, height, 1)
                             mipmapLevel:0 slice:layer];
                [adapter_texture getBytes:adapter_pixels[layer] bytesPerRow:width * 4
                             bytesPerImage:max_byte_count
                              fromRegion:MTLRegionMake3D(0, 0, 0, width, height, 1)
                              mipmapLevel:0 slice:layer];
                if (memcmp(native_pixels[layer], adapter_pixels[layer], max_byte_count) != 0) {
                    size_t mismatch = 0;
                    while (mismatch < max_byte_count && native_pixels[layer][mismatch] == adapter_pixels[layer][mismatch]) mismatch += 1;
                    fprintf(stderr, "metal-pixel: layered %s %s slice %zu mismatch at byte %zu native=%u adapter=%u statuses=%ld/%ld\n",
                            parallel_index == 0 ? "render" : "parallel", format == MTLPixelFormatRGBA8Unorm ? "RGBA8" : "BGRA8",
                            layer, mismatch,
                            mismatch < max_byte_count ? native_pixels[layer][mismatch] : 0,
                            mismatch < max_byte_count ? adapter_pixels[layer][mismatch] : 0,
                            (long)native_command_buffer.status, (long)adapter_command_buffer.status);
                    fail_with_error("native layered render error", native_command_buffer.error);
                    fail_with_error("adapter layered render error", adapter_command_buffer.error);
                    return 185;
                }
            }
            if (native_command_buffer.status != MTLCommandBufferStatusCompleted ||
                adapter_command_buffer.status != MTLCommandBufferStatusCompleted) {
                fprintf(stderr, "metal-pixel: layered %s %s command did not complete\n",
                        parallel_index == 0 ? "render" : "parallel", format == MTLPixelFormatRGBA8Unorm ? "RGBA8" : "BGRA8");
                return 186;
            }
            if (memcmp(native_pixels[0], native_pixels[1], max_byte_count) == 0 ||
                memcmp(native_pixels[1], native_pixels[2], max_byte_count) != 0 ||
                memcmp(native_pixels[2], native_pixels[3], max_byte_count) != 0) {
                fprintf(stderr, "metal-pixel: layered direct primitive base-instance routing failed\n");
                return 187;
            }
        }
    }
    return 0;
}

