                [subbyte_copy_encoder copyFromTensor:subbyte_copy_source
                                        sourceOrigin:[[MTLTensorExtents alloc] initWithRank:2 values:(const NSInteger[]){0, 0}]
                                    sourceDimensions:tensor_dimensions
                                           toTensor:subbyte_copy_destination
